mapper.select:
SELECT BILL_DATE, MAX(PAYMENT_CHANNEL) AS PAYMENT_CHANNEL, PAYMENT_VENDOR, MAX(CHANNEL_NAME) AS CHANNEL_NAME, COUNT(1) AS TXN_COUNT, SUM(NVL(ORDER_AMOUNT, 0)) AS ORDER_AMOUNT, SUM(NVL(TRANSACTION_AMOUNT, 0)) AS TRANSACTION_AMOUNT, SUM(NVL(FEE_AMOUNT, 0)) AS FEE_AMOUNT, SUM(NVL(SETTLEMENT_AMOUNT, 0)) AS SETTLEMENT_AMOUNT, SUM(NVL(DISCOUNT_AMOUNT, 0)) AS DISCOUNT_AMOUNT FROM RECON_THIRD_BILL WHERE BILL_DATE >= #{billDateStart,jdbcType=VARCHAR} AND BILL_DATE <= #{billDateEnd,jdbcType=VARCHAR}
AND PAYMENT_CHANNEL = #{paymentChannel,jdbcType=VARCHAR}
AND PAYMENT_VENDOR = #{paymentVendor,jdbcType=VARCHAR}
GROUP BY BILL_DATE, PAYMENT_VENDOR ORDER BY BILL_DATE, PAYMENT_VENDOR
